open('references.bib', 'w').write(BIB)

def sh(cmd):
    return subprocess.run(cmd, shell=True, capture_output=True, text=True)
for cmd in ('pdflatex -interaction=nonstopmode -halt-on-error paper.tex', 'bibtex paper', 'pdflatex -interaction=nonstopmode -halt-on-error paper.tex', 'pdflatex -interaction=nonstopmode -halt-on-error paper.tex'):
    r = sh(cmd)
    if r.returncode != 0 and not cmd.startswith('bibtex'):
        print(r.stdout[-3000:]); sys.exit(f"ERROR DE LATEX en: {cmd}")
log = open('paper.log', errors='ignore').read()
bad = [l for l in log.splitlines() if re.search(r'^! ', l) or 'undefined' in l.lower() and ('Citation' in l or 'Reference' in l) or 'Label(s) may have changed' in l]
if bad: print('\n'.join(bad[:10])); sys.exit("referencias/citas sin resolver o errores en el log")
bl = open('paper.blg', errors='ignore').read() if os.path.exists('paper.blg') else ''
if 'error message' in bl.lower() and re.search(r'\(There (was|were) \d+ error', bl): print(bl[-1500:]); sys.exit("errores de BibTeX")
npages = re.search(r'Output written on paper.pdf \((\d+) page', log)
print(f"OK: paper.tex, references.bib, paper.pdf ({npages.group(1) if npages else '?'} paginas); cifras leidas de discovery_results.json")
for ext in ('aux', 'bbl', 'blg', 'out', 'log'):
    pass
